    EStopTimer : TON;
END_VAR

EStopTimer(IN := NOT EStop, PT := T#0s);

IF EStop THEN
    Motor := FALSE;
    MotorLatch := FALSE;
ELSIF EStopTimer.Q THEN
    IF Start AND NOT Stop THEN
        MotorLatch := TRUE;
    END_IF;
    Motor := MotorLatch;
ELSIF Stop THEN
    MotorLatch := FALSE;
    Motor := FALSE;
END_IF;

Motor := Motor AND NOT EStopTimer.Q;
END_PROGRAM

