END_VAR

IF EStop = FALSE THEN
    EStop_Activated := TRUE;
END_IF;

IF EStop_Activated THEN
    Motor := FALSE;
    Motor_Latched := FALSE;
ELSE
    IF Start AND NOT Motor_Latched THEN
        Motor_Latched := TRUE;
        Motor := TRUE;
    END_IF;

    IF Stop OR EStop_Activated THEN
        Motor_Latched := FALSE;
        Motor := FALSE;
    END_IF;
END_IF;

Motor := Motor AND NOT EStop_Activated;
