PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prevLevel : INT := 0;
    lowLimit : INT := 10;
    highLimit : INT := 90;
    pumpTimer : TON;
END_VAR

pumpTimer(IN := TRUE, PT := T#5s);

IF Level <= lowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= highLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

IF Level >= highLimit AND prevLevel < highLimit THEN
    pumpTimer(IN := TRUE);
END_IF;

prevLevel := Level;

END_PROGRAM

