PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    PumpTimer : TON;
END_VAR

// Initialize the timer
PumpTimer(IN := FALSE, PT := T#0s);

// Logic for maintaining tank level with hysteresis
IF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
    // Ensure the pump does not run when the level is at or above the high limit
    PumpTimer(IN := FALSE, PT := T#0s);
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Reset the pump timer if the level is within the safe range
IF Level > LowLimit AND Level < HighLimit THEN
    PumpTimer(IN := TRUE, PT := T#0s);
END_IF;

// Check if the pump should be turned off after a delay
IF PumpTimer.Q THEN
    PumpIn := FALSE;
END_IF;
END_PROGRAM

