        PumpIn := TRUE;
        ValveOut := FALSE;
    ELSIF Level >= highLimit THEN
        PumpIn := FALSE;
        ValveOut := TRUE;
    ELSE
        PumpIn := FALSE;
        ValveOut := FALSE;
    END_IF;

    // Prevent overflow by opening the outlet valve if the level is at or above the high limit
    IF Level >= highLimit THEN
        ValveOut := TRUE;
    END_IF;
END_IF;

