PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
    HighLimit : CONST INT := 90;
    LowLimit : CONST INT := 10;
END_VAR

// Check for high limit first to ensure safety
IF Level >= HighLimit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= LowLimit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Implement hysteresis logic
IF NOT PumpIn AND Level < HighLimit THEN
    PumpInTimer(IN := TRUE, PT := T#1s);
    PumpIn := PumpInTimer.Q;
ELSIF PumpIn AND Level >= HighLimit THEN
    PumpInTimer(IN := FALSE, PT := T#1s);
    PumpIn := NOT PumpInTimer.Q;
END_IF;

IF Level >= HighLimit THEN
    ValveOutTimer(IN := TRUE, PT := T#1s);
    ValveOut := ValveOutTimer.Q;
ELSEIF Level < HighLimit THEN
    ValveOutTimer(IN := FALSE, PT := T#1s);
    ValveOut := NOT ValveOutTimer.Q;
END_IF;
END_PROGRAM

