PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorATimer : TON;
    DoorBTimer : TON;
    LastOpenA_Cmd : BOOL := FALSE;
    LastOpenB_Cmd : BOOL := FALSE;
END_VAR

// Reset timers if commands change
DoorATimer(IN := OpenA_Cmd AND NOT OpenB_Cmd, PT := T#0s);
DoorBTimer(IN := OpenB_Cmd AND NOT OpenA_Cmd, PT := T#0s);

// Set outputs based on timers and last state
IF DoorATimer.Q THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF DoorBTimer.Q THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

// Update last command states for next cycle
LastOpenA_Cmd := OpenA_Cmd;
LastOpenB_Cmd := OpenB_Cmd;
END_PROGRAM

