PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorA_Opened : BOOL := FALSE;
    DoorB_Opened : BOOL := FALSE;
    PriorityTimer_A : TON;
    PriorityTimer_B : TON;
END_VAR

// Check if both doors are requested to open simultaneously
IF OpenA_Cmd AND OpenB_Cmd THEN
    // Give priority to Door A
    DoorA := TRUE;
    DoorB := FALSE;
    PriorityTimer_A(IN := TRUE, PT := T#0s);
    PriorityTimer_B(IN := FALSE, PT := T#0s);
ELSIF OpenA_Cmd THEN
    // Check if Door B is not opened
    IF NOT DoorB_Opened THEN
        DoorA := TRUE;
        DoorB := FALSE;
        PriorityTimer_A(IN := TRUE, PT := T#0s);
        PriorityTimer_B(IN := FALSE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        PriorityTimer_A(IN := FALSE, PT := T#0s);
        PriorityTimer_B(IN := FALSE, PT := T#0s);
    END_IF
ELSIF OpenB_Cmd THEN
    // Check if Door A is not opened
    IF NOT DoorA_Opened THEN
        DoorA := FALSE;
        DoorB := TRUE;
        PriorityTimer_B(IN := TRUE, PT := T#0s);
        PriorityTimer_A(IN := FALSE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        DoorB := FALSE;
        PriorityTimer_A(IN := FALSE, PT := T#0s);
        PriorityTimer_B(IN := FALSE, PT := T#0s);
    END_IF
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    PriorityTimer_A(IN := FALSE, PT := T#0s);
    PriorityTimer_B(IN := FALSE, PT := T#0s);
END_IF

// Update the status based on the timers
DoorA := DoorA AND PriorityTimer_A.Q;
DoorB := DoorB AND PriorityTimer_B.Q;

END_PROGRAM

