IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND EStop THEN
            State := 1;
            FillValve := TRUE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    1: -- Fill
        IF Level >= LVL_HIGH OR NOT EStop THEN
            State := 2;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;

    2: -- Heat
        IF Temp >= TEMP_SET AND Level >= LIQ_MIN AND NOT EStop THEN
            State := 3;
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        ELSEIF NOT EStop THEN
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    3: -- React
        ReactTimer(IN := TRUE, PT := PT_REACT);
        IF ReactTimer.Q AND Level >= LIQ_MIN AND NOT EStop THEN
            State := 4;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSEIF NOT EStop THEN
            Heater := TRUE;
            Agitator := TRUE;
        END_IF;

    4: -- Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
END_CASE;

-- Safety checks
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF NOT EStop THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

IF Level < LIQ_MIN AND (Heater OR Agitator) THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

