    FillTimer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: -- Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: -- Fill
        FillValve := TRUE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH THEN
            State := 2;
            FillValve := FALSE;
        END_IF;

    2: -- Heat
        Heater := TRUE;
        Agitator := TRUE;

        IF Temp >= TEMP_SET THEN
            State := 3;
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    3: -- React
        Heater := TRUE;
        Agitator := TRUE;

        IF FillTimer.Q THEN
            State := 4;
            Heater := FALSE;
            Agitator := FALSE;
        ELSE
            FillTimer(IN := TRUE, PT := PT_REACT);
        END_IF;

    4: -- Drain
        FillValve := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
            DrainValve := FALSE;
        END_IF;
END_CASE;
END_PROGRAM

