    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    MainK : BOOL;
    StarK : BOOL;
    DeltaK : BOOL;
END_VAR

VAR
    State : INT := 0;
    PT_STAR : TIME := T#3s;
    StarTimer : TON;
END_VAR

StarTimer(IN := (State = 1), PT := PT_STAR);

CASE State OF
    0: // Off
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;

        IF StartPB AND EStop THEN
            State := 1;
        END_IF;

    1: // Star
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;

        IF StarTimer.Q THEN
            State := 2;
        END_IF;

        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;

    2: // Delta
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;

        IF StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE

// Safety check: StarK and DeltaK should never be energized simultaneously
IF StarK AND DeltaK THEN
    MainK := FALSE;
    StarK := FALSE;
    DeltaK := FALSE;
    State := 0;
END_IF
END_PROGRAM

