PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR

VAR
    State : INT := 0;
    TFill : TON;
    TDrain : TON;
END_VAR

CONSTANT
    HIGH : INT := 90;
    LOW : INT := 10;
END_CONSTANT

CASE State OF
    0: -- Idle
        IF EStop THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSIF StartCycle AND Level < HIGH THEN
            State := 1;
            Pump := TRUE;
            Valve := FALSE;
        ELSE
            Pump := FALSE;
            Valve := FALSE;
        END_IF;

    1: -- Filling
        IF EStop OR Level >= HIGH THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSE
            Pump := TRUE;
            Valve := FALSE;
        END_IF;

    2: -- Draining
        IF EStop OR Level <= LOW THEN
            State := 0;
            Pump := FALSE;
            Valve := FALSE;
        ELSE
            Pump := FALSE;
            Valve := TRUE;
        END_IF;
END_CASE;

-- Safety conditions
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= HIGH AND Pump THEN
    Pump := FALSE;
END_IF;

IF Level <= LOW AND Valve THEN
    Valve := FALSE;
END_IF;
END_PROGRAM

