        END_IF;

    2: // Ignition trial
        IgnitionTimer(IN := TRUE, PT := PT_IGN);
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := TRUE;

        IF Flame THEN
            State := 3;
        ELSIF IgnitionTimer.Q THEN
            State := 0;
        END_IF;

    3: // Run
        Fan := TRUE;
        Fuel := TRUE;
        Ignition := FALSE;

        IF NOT Flame OR StopPB OR NOT EStop THEN
            State := 0;
        END_IF;
END_CASE;

IF NOT Fan THEN
    Fuel := FALSE;
END_IF;

IF NOT EStop THEN
    State := 0;
    Fan := FALSE;
    Fuel := FALSE;
    Ignition := FALSE;
END_IF;

